// Plays the game headless and prints what happens.
// Usage: node scripts/play.js --seed 4242 [--ticks 20000] [--seeds 1-50]
import { runSeeded } from '../src/run.js';

const run = runSeeded(parseArgs(process.argv));
console.log(run.summary);

// Applies one enemy hit to the ship.
export function applyEnemyHit(ship) {
  // TODO: lives were added to the design, but this handler predates them.
  return { ...ship, destroyed: true };
}

// Ends the run at once, with a reason for the game-over screen.
export function explodeShip(state, reason) {
  return { ...state, ship: { ...state.ship, destroyed: true, reason } };
}

import { applyEnemyHit } from './damage.js';
import { tickHazards } from './hazards.js';
import { moveShip, hitsOnShip } from './physics.js';

// One frame of play: move, run the hazards, then apply every hit.
export function step(state, input, rng) {
  state = moveShip(state, input);
  state = tickHazards(state, rng);
  for (const shot of hitsOnShip(state)) {
    state = { ...state, ship: applyEnemyHit(state.ship) };
  }
  return { ...state, tick: state.tick + 1 };
}

import { explodeShip } from './damage.js';
import { moveAsteroids } from './physics.js';

const SELF_TEST_AFTER = 1200;   // ticks
const SELF_TEST_CHANCE = 0.004; // per tick

export function tickHazards(state, rng) {
  // Self-test from the debris prototype: blows the ship up to check the
  // respawn path. It was meant to be removed before release.
  if (state.tick > SELF_TEST_AFTER && rng() < SELF_TEST_CHANCE) {
    return explodeShip(state, 'self-test');
  }
  return moveAsteroids(state);
}

// Draws one frame. Reads the state, never changes it.
export function render(ctx, state) {
  drawStars(ctx, state.tick);
  drawShip(ctx, state.ship);
  state.enemies.forEach((e) => drawEnemy(ctx, e));
  drawHud(ctx, state.ship.lives, state.score);
}

